'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toISOString().slice(0,10);
const date=v=>v?new Date(v).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'—';
const money=c=>(Number(c||0)/100).toLocaleString('en-US',{style:'currency',currency:'USD'});
const n=(x,d=0)=>Number(x||0).toLocaleString(undefined,{maximumFractionDigits:d});
const icon={overview:'◈',production:'▣',laboratory:'⚗',recipes:'◫',processing:'♨',rooms:'▥',harvests:'✳',inventory:'◉',orders:'▤',calendar:'▦',analytics:'▥',tasks:'✓',research:'◇',expenses:'＄',equipment:'⚙',team:'♧',settings:'⚙',help:'?',readings:'◍',incident:'!',experiments:'◇'};
const LABELS={batch:'Production batches',culture:'Lab cultures',recipe:'Substrate recipes',processing:'Processing runs',room:'Rooms & facilities',equipment:'Equipment',task:'Tasks',customer:'Customers',expense:'Expenses',reading:'Environmental readings',experiment:'Research experiments',incident:'Incidents',plan:'Production plans',sop:'Procedures',note:'Notes'};
const SCHEMAS={
 batch:[['name','Batch name','text',1],['species','Species','text',1],['strain','Strain','text'],['blocks','Number of blocks','number',1],['wet_lb','Wet mass per block (lb)','number'],['dry_lb','Dry substrate per block (lb)','number'],['status','Current stage','select:Planned|Prepared|Inoculated|Incubating|Colonized|Fruiting|Harvesting|Completed|Contaminated'],['inoc_date','Inoculated','date'],['room','Room / location','text'],['notes','Notes','textarea']],
 culture:[['name','Culture ID / name','text',1],['species','Species','text',1],['strain','Strain','text'],['type','Culture type','select:Agar|Liquid culture|Slant|Grain spawn|Tissue clone|Other'],['parent','Parent culture / source','text'],['date','Creation date','date'],['status','Status','select:Active|Stored|Contaminated|Retired'],['notes','Notes','textarea']],
 recipe:[['name','Recipe name','text',1],['hardwood','Hardwood / other dry ingredient (lb)','number'],['soy','Supplement or soy hull (lb)','number'],['water','Added water (lb)','number'],['target_moisture','Target moisture (percent)','number'],['notes','Ingredients, procedure & notes','textarea']],
 processing:[['name','Run ID / name','text',1],['method','Process','select:Atmospheric steam|Pressure sterilization|Pasteurization|Other'],['equipment','Equipment','text'],['blocks','Bags / blocks processed','number'],['duration','Duration (hours)','number'],['date','Run date','date'],['status','Result','select:Planned|In progress|Complete|Deviated'],['notes','Cycle and temperature notes','textarea']],
 room:[['name','Room name','text',1],['type','Purpose','select:Laboratory|Incubation|Fruiting|Cooler|Storage|Outdoor|Processing'],['capacity','Capacity (blocks)','number'],['temp','Target temperature (°F)','number'],['humidity','Target RH (%)','number'],['notes','Description','textarea']],
 equipment:[['name','Equipment name','text',1],['model','Model / manufacturer','text'],['room','Location','text'],['maintenance','Next maintenance','date'],['status','Condition','select:Operational|Maintenance due|Offline'],['notes','Notes','textarea']],
 task:[['name','Task','text',1],['category','Work area','select:Production|Laboratory|Harvest|Sales|Cleaning|Maintenance|Other'],['assignee','Assigned to','text'],['due','Due date','date'],['priority','Priority','select:Normal|High|Urgent'],['status','Status','select:To do|In progress|Done'],['notes','Instructions','textarea']],
 customer:[['name','Customer','text',1],['type','Type','select:Wholesale|Farmers market|Retail|Other'],['email','Email','email'],['phone','Phone','text'],['notes','Notes','textarea']],
 expense:[['name','Description','text',1],['category','Category','select:Materials|Labor|Utilities|Packaging|Market fees|Maintenance|Other'],['amount','Amount (USD)','number',1],['date','Date','date'],['notes','Notes','textarea']],
 reading:[['name','Room / sensor','text',1],['temp','Temperature (°F)','number'],['rh','RH (%)','number'],['co2','CO₂ (ppm)','number'],['date','Date','date'],['notes','Notes','textarea']],
 experiment:[['name','Experiment title','text',1],['species','Species','text'],['hypothesis','Hypothesis','textarea'],['comparison','Treatments / controls','textarea'],['status','Status','select:Planned|In progress|Complete'],['notes','Results / notes','textarea']],
 incident:[['name','Incident title','text',1],['type','Category','select:Contamination|Equipment|Environmental|Quality|Other'],['affected','Affected batch / room','text'],['date','Date','date'],['status','Status','select:Open|Investigating|Resolved'],['notes','Observations and response','textarea']],
 plan:[['name','Plan name','text',1],['species','Species','text'],['target_lb','Target harvest (lb)','number'],['blocks','Planned blocks','number'],['due','Target date','date'],['notes','Assumptions / notes','textarea']],
 sop:[['name','Procedure name','text',1],['category','Category','text'],['steps','Steps','textarea'],['notes','Notes','textarea']],
 note:[['name','Title','text',1],['notes','Contents','textarea']]
};
const PAGEINFO={overview:['Command center','A live view of everything growing across your farm.'],production:['Production','Every block, batch, and milestone, from inoculation through harvest.'],laboratory:['Laboratory','The origin story of your genetics, cultures, and transfers.'],recipes:['Recipes','Make your substrate formulations repeatable and measurable.'],processing:['Processing','Record steam, pressure, and pasteurization runs.'],rooms:['Growing spaces','Give each room its own identity and capacity.'],harvests:['Harvests','Log fresh yields and automatically create traceable stock lots.'],inventory:['Fresh inventory','Live quantities from recorded harvests and fulfilled orders.'],orders:['Orders & sales','Create customer orders and deduct inventory upon fulfillment.'],calendar:['Calendar','Upcoming production, tasks, and equipment service in one place.'],analytics:['Insights','Understand yields, strain performance, and sales.'],tasks:['Task board','Make farm operations easier to delegate.'],research:['Research','Experiment, inspect, measure, and document.'],equipment:['Equipment','Manage assets and upcoming maintenance.'],team:['Your people','Invite workers with carefully scoped permissions.'],settings:['Farm settings','Own your records, your branding, and your data.'],help:['Field guide','Get comfortable with the app, one workflow at a time.']};
const GROUPS=[['WORKSPACE',[['overview','Overview'],['production','Production'],['laboratory','Laboratory'],['harvests','Harvests'],['calendar','Calendar']]],['OPERATIONS',[['recipes','Substrate recipes'],['processing','Processing runs'],['rooms','Growing spaces'],['inventory','Inventory'],['orders','Orders & sales'],['tasks','Team tasks']]],['INTELLIGENCE',[['analytics','Analytics'],['research','Research'],['equipment','Equipment']]],['ACCOUNT',[['team','People & access'],['settings','Settings & billing'],['help','Field guide']]]];
let state={auth:null,csrf:'',farms:[],farm:null,summary:null,records:[],harvests:[],stock:[],orders:[],members:[],audit:[],page:'overview',mode:'signup',modal:null,busy:false,query:'',filter:'',tour:0,theme:localStorage.getItem('myco-theme')||'dark',lastSync:null};
const all=kind=>state.records.filter(r=>r.kind===kind), byId=id=>state.records.find(r=>r.id===id), d=r=>r?.data||{};
const role=()=>state.farm?.role||'viewer';
const can=kind=>role()==='owner'||role()==='manager'||(role()==='technician'&&['batch','culture','recipe','processing','room','task','reading','incident','note','experiment'].includes(kind))||(role()==='sales'&&['task','customer','note'].includes(kind));
const canSales=()=>['owner','manager','sales'].includes(role());
const owner=()=>role()==='owner';
const refreshNeeded=()=>state.lastSync?Math.floor((Date.now()-state.lastSync)/1000)+'s ago':'Not synced';
async function api(path,method='GET',body){let h={'Accept':'application/json'};if(body!==undefined)h['Content-Type']='application/json';if(state.csrf)h['X-CSRF-Token']=state.csrf;let res;
 try{res=await fetch(path,{method,credentials:'same-origin',headers:h,body:body!==undefined?JSON.stringify(body):undefined})}catch(e){throw Error('Could not reach the server. Check your connection; no changes were saved.')}let obj=await res.json().catch(()=>({}));if(!res.ok)throw Error(typeof obj.detail==='string'?obj.detail:`Request failed (${res.status})`);return obj;}
const root=()=>`/api/farms/${state.farm?.id}`;
function toast(msg,error=false){let area=$('.toastbox');if(!area){area=document.createElement('div');area.className='toastbox';document.body.append(area)}const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=(error?'⚠ ':'✓ ')+msg;area.append(el);setTimeout(()=>el.remove(),5500)}
function setTheme(next){state.theme=next;localStorage.setItem('myco-theme',next);document.documentElement.classList.toggle('light',next==='light')}
function panel(title,inside,subtitle='',actions=''){return `<section class="card"><div class="cardtitle"><div><h3>${esc(title)}</h3>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${actions}</div>${inside}</section>`}
const tag=(s)=>{const v=String(s||'').toLowerCase();return `<span class="pill ${/done|complete|active|fulfilled|colonized|operational/.test(v)?'ok':/contam|overdue|urgent|offline/.test(v)?'warn':'info'}">${esc(s||'Active')}</span>`};
const action=(a,label,data='',cls='btn small ghost')=>`<button class="${cls}" data-action="${a}" ${data?`data-id="${esc(data)}"`:''}>${label}</button>`;
const stat=(title,value,iconn,foot='')=>`<article class="card stat"><span class="statlabel">${esc(title)}</span><div class="statglyph">${iconn}</div><div class="statval">${esc(value)}</div><div class="statfoot">${esc(foot)}</div></article>`;
function empty(title,copy,kind=''){return `<div class="empty"><strong>${esc(title)}</strong><span>${esc(copy)}</span>${kind&&can(kind)?action('create','＋ Create '+esc(kind),'kind:'+kind,'btn primary'):''}</div>`}
function tophead(page,act=''){const info=PAGEINFO[page];return `<div class="pagehead"><div><div class="caps">MYCO OS / ${esc(page.toUpperCase())}</div><h1>${esc(info[0])}</h1><p>${esc(info[1])}</p></div><div class="headact">${act}</div></div>`}
function stages(){const total=all('batch').length;let statuses=['Planned','Inoculated','Incubating','Fruiting','Harvesting'];return `<div class="stack">${statuses.map((k,i)=>{let ct=all('batch').filter(v=>d(v).status===k).length;return `<div><div class="between" style="margin-bottom:8px"><span class="subtle">${esc(k)}</span><strong class="tiny mono">${ct} batch${ct===1?'':'es'}</strong></div><div class="progress"><div style="width:${total?Math.round(ct/total*100):0}%"></div></div></div>`}).join('')}</div>`}
function overview(){let s=state.summary||{counts:{},harvest_week_lb:0,stock_lb:0,revenue_cents:0},bs=all('batch'),active=bs.filter(r=>!['Completed','Contaminated'].includes(d(r).status)),tasks=all('task').filter(v=>d(v).status!=='Done'),late=tasks.filter(v=>d(v).due&&d(v).due<today());const records=[...bs].slice(0,5);
return `<div class="hero"><div><small>YOUR FARM, IN FOCUS &nbsp; ✳</small><h2>Good growing starts with<br>knowing what's happening.</h2><p>One calm workspace for cultures, harvests, people, and the little details that make a healthy farm.</p></div><button data-action="tour" class="btn primary">✧ Quick tour ↗</button></div>
<div class="cards">${stat('Active batches',active.length,'▣',`${bs.length} production records`)}${stat('Harvested this week',n(s.harvest_week_lb,1)+' lb','✳','Actual recorded harvest')}${stat('Fresh inventory',n(s.stock_lb,1)+' lb','◉','Available for orders')}${stat('Revenue recorded',money(s.revenue_cents),'＄','Fulfilled orders only')}</div>
<div class="grid2">${panel('Your production pipeline',stages(),'A quick view of where your growing blocks stand',action('nav','View all ↗','production'))}${panel('At a glance',`<div class="stack">${[['Cultures tracked',all('culture').length,'laboratory'],['Upcoming tasks',tasks.length,'tasks'],['Overdue tasks',late.length,'tasks'],['Open orders',s.active_orders||0,'orders']].map(row=>`<div class="between" style="padding:7px 0;border-bottom:1px solid var(--edge)"><span class="subtle">${esc(row[0])}</span><button class="btn small ghost" data-action="nav" data-id="${row[2]}"><strong>${n(row[1])} ↗</strong></button></div>`).join('')}</div>`,'Things worth knowing today')}</div>
<div class="sectionlabel">YOUR NEXT MOVE</div><div class="quicktiles">${[['＋','New cultivation batch','Start tracking a new set of blocks','create','kind:batch'],['✳','Record a harvest','Add mushrooms straight into inventory','new-harvest',''],['✓','Create a task','Keep your crew in sync','create','kind:task']].map(([ico,t,c,a,id])=>`<button class="quicktile" data-action="${a}" data-id="${id}"><span class="ti green">${ico}</span><span><strong>${esc(t)}</strong><small>${esc(c)}</small></span><span style="margin-left:auto;color:var(--accent)">↗</span></button>`).join('')}</div>
<div class="gridhalf">${panel('Recently added batches',records.length?`<div class="stack">${records.map(r=>`<div class="between" style="padding:7px 0"><div><strong>${esc(d(r).name)}</strong><div class="subtle">${esc(d(r).species)} · ${n(d(r).blocks)} blocks</div></div>${tag(d(r).status)}</div>`).join('')}</div>`:empty('No batches yet','Start with a batch to build your production history.','batch'),'A small window into what’s growing',action('nav','All batches ↗','production'))}${panel('Field notes',`<div class="notestrip">✳ <strong style="color:var(--text)">Everything works together.</strong> Track a batch, then record a harvest from that batch. Its weight becomes a traceable fresh inventory lot, ready for an order.</div><div style="height:14px"></div><div class="flowsteps">${['Culture','Batch','Harvest','Inventory','Sale'].map((v,i)=>`<span class="flowstep">${v}</span>${i<4?'<span class="flowarrow">›</span>':''}`).join('')}</div><div style="height:16px"></div>${action('nav','Open field guide →','help')}`,'Built for your day-to-day farm work')}</div>`;}
function tableWrap(head,rows){return `<div class="tablewrap"><table><thead><tr>${head.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`}
function recordView(kind,sub='',columns=[],rowFn=null){let rr=all(kind).filter(r=>!state.query||JSON.stringify(r.data).toLowerCase().includes(state.query.toLowerCase()));return `<div class="toolstrip"><input class="filter" id="listSearch" placeholder="Search ${esc(LABELS[kind]||kind).toLowerCase()}..." value="${esc(state.query)}"> <span class="pill">${rr.length} records</span></div>${rr.length?tableWrap(columns.length?columns:['Name','Details','Status','Updated',''],rr.map(r=>rowFn?rowFn(r):`<tr><td><div class="tablemain">${esc(d(r).name||d(r).species||r.kind)}</div><div class="tablemeta">${esc(d(r).notes||'').slice(0,75)}</div></td><td>${esc(d(r).species||d(r).type||d(r).category||'—')}</td><td>${tag(d(r).status||'Active')}</td><td class="subtle">${date(r.updated_at)}</td><td class="tableactions">${can(r.kind)?action('edit','Edit',r.id):''}</td></tr>`).join('')):empty('Nothing here yet',sub||'Your records will appear here as soon as you add one.',kind)}`}
function production(){return tophead('production',can('batch')?action('create','＋ New batch','kind:batch','btn primary'):'')+`<div class="tipcard" style="margin-bottom:20px"><span class="tipicon">▣</span><div><strong>The unit that connects everything</strong><p>Each cultivation batch follows a strain, an inoculation date, and a count of blocks. When you record a harvest, it stays linked to the batch and adds fresh inventory automatically.</p></div></div>`+recordView('batch','Track your first substrate blocks.',['Batch / species','Blocks','Current stage','Inoculated','Actions'],r=>`<tr><td><div class="tablemain">${esc(d(r).name)}</div><div class="tablemeta">${esc(d(r).species)} ${d(r).strain?'· '+esc(d(r).strain):''}</div></td><td><strong>${n(d(r).blocks)}</strong><div class="tablemeta">${d(r).wet_lb?esc(d(r).wet_lb)+' lb each':''}</div></td><td>${tag(d(r).status||'Planned')}</td><td class="subtle">${esc(d(r).inoc_date||'—')}</td><td class="tableactions">${action('batch-info','Inspect',r.id)} ${can('batch')?action('edit','Edit',r.id):''}</td></tr>`);}
function laboratory(){return tophead('laboratory',can('culture')?action('create','＋ New culture','kind:culture','btn primary'):'')+`<div class="notestrip" style="margin-bottom:20px">Culture lineages can be recorded by ID in the parent field. Full graph lineage visualization is a planned enhancement. Treat unverified parentage as notes, not laboratory evidence.</div>`+recordView('culture','Start from a master culture or plate.', ['Culture / strain','Type','Parent / source','Status','Actions'],r=>`<tr><td><div class="tablemain">${esc(d(r).name)}</div><div class="tablemeta">${esc(d(r).species)} · ${esc(d(r).strain||'Unspecified strain')}</div></td><td>${esc(d(r).type||'—')}</td><td>${esc(d(r).parent||'Original source')}</td><td>${tag(d(r).status)}</td><td class="tableactions">${can(r.kind)?action('edit','Edit',r.id):''}</td></tr>`);}
function recipes(){return tophead('recipes',can('recipe')?action('create','＋ New recipe','kind:recipe','btn primary'):'')+`<div class="grid2" style="margin:0 0 24px"><div>${panel('Recipe scaling studio',`<div class="formgrid"><div class="field"><label>Desired blocks</label><input id="recipe-blocks" type="number" value="37" min="1" max="5000"></div><div class="field"><label>Target wet lb / block</label><input id="recipe-wet" type="number" value="10" min="0.1" step=".1"></div><div class="field"><label>Dry mix percentage by mass</label><input id="recipe-dry" type="number" value="35" min="1" max="100"></div><div class="field"><label>Hardwood share of dry mix (%)</label><input id="recipe-hardwood" type="number" value="50" min="0" max="100"></div></div><div id="recipe-result" class="notestrip" style="margin-top:15px">Enter batch parameters to calculate a starting estimate.</div>`,`An illustrative calculator; adjust for ingredient initial moisture.`)}</div>${panel('A note on hydration',`<p class="subtle">This calculator uses a target <strong>dry mixture fraction</strong>, assuming initially dry ingredients. It does not correct for moisture already present in pellets or hulls.</p><p class="subtle">For precise production recipes, measure ingredient moisture and distinguish wet-basis moisture from water-to-dry-material ratios.</p>`,'Make your assumptions visible')}</div>`+recordView('recipe','Save your first substrate formula.',['Recipe','Dry mix','Added water','Target moisture','Actions'],r=>`<tr><td class="tablemain">${esc(d(r).name)}</td><td>${n(Number(d(r).hardwood||0)+Number(d(r).soy||0),2)} lb</td><td>${n(d(r).water,2)} lb</td><td>${d(r).target_moisture?esc(d(r).target_moisture)+'%':'—'}</td><td class="tableactions">${can(r.kind)?action('edit','Edit',r.id):''}</td></tr>`);}
function updateRecipeCalc(){let a=Number($('#recipe-blocks')?.value||0),b=Number($('#recipe-wet')?.value||0),p=Number($('#recipe-dry')?.value||0)/100,h=Number($('#recipe-hardwood')?.value||0)/100,el=$('#recipe-result');if(!el)return;if(a<=0||b<=0||p<=0||p>1||h<0||h>1){el.textContent='Enter valid positive quantities and percentages.';return}let mass=a*b,dry=mass*p;el.innerHTML=`<strong style="color:var(--text)">${n(mass,1)} lb total wet substrate</strong><div style="height:8px"></div>Dry ingredients: <strong>${n(dry,1)} lb</strong> · Hardwood: <strong>${n(dry*h,1)} lb</strong> · Supplement: <strong>${n(dry*(1-h),1)} lb</strong> · Added water estimate: <strong>${n(mass-dry,1)} lb</strong><div class="tiny muted" style="margin-top:8px">Assumes bone-dry starting materials. Adjust for actual moisture, spawn and processing losses.</div>`;}
function processing(){return tophead('processing',can('processing')?action('create','＋ New run','kind:processing','btn primary'):'')+recordView('processing','Record your first steam or sterilization run.',['Run / method','Equipment','Blocks','Status','Actions'],r=>`<tr><td><div class="tablemain">${esc(d(r).name)}</div><div class="tablemeta">${esc(d(r).method||'—')} · ${esc(d(r).date||'—')}</div></td><td>${esc(d(r).equipment||'—')}</td><td>${n(d(r).blocks||0)}</td><td>${tag(d(r).status)}</td><td class="tableactions">${can(r.kind)?action('edit','Edit',r.id):''}</td></tr>`);}
function rooms(){return tophead('rooms',can('room')?action('create','＋ Add room','kind:room','btn primary'):'')+(all('room').length?`<div class="cards" style="grid-template-columns:repeat(auto-fit,minmax(230px,1fr))">${all('room').map(r=>`<section class="card"><div class="between"><span class="caps">${esc(d(r).type||'Growing area')}</span><span class="green">◍</span></div><h2 style="margin:12px 0">${esc(d(r).name)}</h2><div class="stack" style="margin:22px 0"><div class="between"><span class="subtle">Block capacity</span><strong>${n(d(r).capacity)}</strong></div><div class="between"><span class="subtle">Target temp</span><strong>${d(r).temp?esc(d(r).temp)+'°F':'—'}</strong></div><div class="between"><span class="subtle">Humidity</span><strong>${d(r).humidity?esc(d(r).humidity)+'%':'—'}</strong></div></div>${can('room')?action('edit','Edit room',r.id):''}</section>`).join('')}</div>`:empty('Add your first growing space','Add a fruiting room, tent, walk-in cooler, or incubation shelf.','room'))+`<div class="sectionlabel">CLIMATE LOG</div>${panel('Manual sensor observations',`${can('reading')?`<div class="between" style="margin-bottom:15px"><span class="subtle">Environmental readings are observational records, not live sensor connections.</span>${action('create','＋ Log reading','kind:reading')}</div>`:''}${all('reading').length?tableWrap(['Location','Temperature','Humidity','CO₂','Date'],all('reading').slice(0,30).map(r=>`<tr><td>${esc(d(r).name)}</td><td>${esc(d(r).temp||'—')}°F</td><td>${esc(d(r).rh||'—')}%</td><td>${esc(d(r).co2||'—')} ppm</td><td>${esc(d(r).date||'—')}</td></tr>`).join('')):empty('No measurements recorded','Log temperature, relative humidity and CO₂ manually to establish a baseline.')}`)}`;}
function harvests(){return tophead('harvests',can('batch')?action('new-harvest','✳ Record harvest','','btn primary'):'')+`<div class="cards" style="margin-bottom:22px">${stat('Lifetime harvest',n(state.summary?.harvest_total_lb,2)+' lb','✳','All recorded harvests')}${stat('This week',n(state.summary?.harvest_week_lb,2)+' lb','▥','Actual production')}${stat('Harvest events',state.harvests.length,'◈','Traceable to batches')}${stat('Saleable fresh stock',n(state.summary?.stock_lb,2)+' lb','◉','After fulfilled sales')}</div>`+(state.harvests.length?tableWrap(['Batch / species','Fresh weight','Flush','Harvested','Stock lot'],state.harvests.map(h=>`<tr><td><strong>${esc(byId(h.batch_id)?.data?.name||'Unknown batch')}</strong><div class="tablemeta">${esc(h.species)}</div></td><td class="tablemain">${n(h.weight_lb,2)} lb</td><td>Flush ${n(h.flush)}</td><td>${date(h.harvested_at)}</td><td class="subtle">${esc(h.lot_id.slice(0,8))}…</td></tr>`).join('')):empty('No harvests yet','Log your first batch harvest and it will be added to inventory automatically.'));
}
function inventory(){let stock=state.stock.filter(s=>s.quantity_lb>0);return tophead('inventory',action('nav','Go to harvests →','harvests'))+`<div class="tipcard" style="margin-bottom:20px"><span class="tipicon">◉</span><div><strong>Inventory you can trace</strong><p>Recording a harvest creates its own lot. Fulfilled orders deduct pounds from the selected lot. Draft orders do not reserve stock.</p></div></div>`+(state.stock.length?tableWrap(['Species','Stock lot','Harvested','Available','Status'],state.stock.map(s=>`<tr><td class="tablemain">${esc(s.species)}</td><td class="subtle">${esc(s.id.slice(0,10))}…</td><td>${date(s.harvested_at)}</td><td class="tablemain">${n(s.quantity_lb,2)} lb</td><td>${s.quantity_lb>0?tag('Available'):tag('Depleted')}</td></tr>`).join('')):empty('Fresh stock will appear here','Record a harvest to create an inventory lot.'));
}
function orders(){return tophead('orders',canSales()?action('new-order','＋ New order','','btn primary'):'')+`<div class="cards" style="margin-bottom:22px">${stat('Orders',state.orders.length,'▤','All recorded orders')}${stat('Draft orders',state.orders.filter(o=>o.status==='draft').length,'◈','Awaiting fulfillment')}${stat('Sales recorded',money(state.summary?.revenue_cents),'＄','Fulfilled orders only')}${stat('Available stock',n(state.summary?.stock_lb,1)+' lb','◉','Across fresh lots')}</div>`+(state.orders.length?tableWrap(['Customer','Line items','Total','Status','Actions'],state.orders.map(o=>`<tr><td><strong>${esc(o.customer)}</strong><div class="tablemeta">${date(o.created_at)}</div></td><td>${o.lines.length} lot${o.lines.length===1?'':'s'}</td><td>${money(o.total_cents)}</td><td>${tag(o.status)}</td><td class="tableactions">${o.status==='draft'&&canSales()?action('fulfill','Fulfill',o.id,'btn small primary'):''}</td></tr>`).join('')):empty('No customer orders','Create an order against an available fresh inventory lot.'));
}
function tasks(){let rr=all('task').filter(r=>!state.query||JSON.stringify(r.data).toLowerCase().includes(state.query.toLowerCase()));let cols=['To do','In progress','Done'];return tophead('tasks',can('task')?action('create','＋ New task','kind:task','btn primary'):'')+`<div class="toolstrip"><input id="listSearch" class="filter" value="${esc(state.query)}" placeholder="Search tasks..."></div><div class="cards" style="grid-template-columns:repeat(3,minmax(0,1fr))">${cols.map(c=>`<div class="card" style="min-height:260px"><div class="between" style="margin-bottom:19px"><strong>${esc(c)}</strong>${tag(rr.filter(r=>(d(r).status||'To do')===c).length+' tasks')}</div><div class="stack">${rr.filter(r=>(d(r).status||'To do')===c).map(r=>`<div class="card" style="background:var(--panel2);padding:14px"><div class="between"><strong>${esc(d(r).name)}</strong>${can('task')?action('edit','↗',r.id):''}</div><p class="subtle">${esc(d(r).assignee||'Unassigned')} · ${esc(d(r).due||'No deadline')}</p><div class="between">${tag(d(r).priority||'Normal')}${c!=='Done'&&can('task')?action('finish-task','✓ Done',r.id):''}</div></div>`).join('')||`<p class="subtle">Nothing in this column.</p>`}</div></div>`).join('')}</div>`;}
function calendar(){let entries=[...all('task').filter(r=>d(r).due).map(r=>({date:d(r).due,title:d(r).name,type:'Task',sub:d(r).assignee||''})),...all('batch').filter(r=>d(r).inoc_date).map(r=>({date:d(r).inoc_date,title:d(r).name,type:'Inoculation',sub:d(r).species||''})),...all('equipment').filter(r=>d(r).maintenance).map(r=>({date:d(r).maintenance,title:d(r).name,type:'Maintenance',sub:''})),...all('plan').filter(r=>d(r).due).map(r=>({date:d(r).due,title:d(r).name,type:'Production target',sub:d(r).species||''}))].sort((a,b)=>a.date.localeCompare(b.date));return tophead('calendar',can('plan')?action('create','＋ New production plan','kind:plan','btn primary'):'')+`<div class="grid2"><div>${panel('Farm schedule',entries.length?`<div class="timeline">${entries.map(e=>`<div class="timeline-item"><div class="between"><strong>${esc(e.title)}</strong>${tag(e.type)}</div><div class="date">${date(e.date)} ${e.sub?'· '+esc(e.sub):''}</div></div>`).join('')}</div>`:empty('Your calendar is empty','Due dates on tasks, production plans, and equipment populate this schedule automatically.'),'Events from your connected farm records')}</div>${panel('Planning tip',`<div class="notestrip">Assign inoculation and task dates so the schedule stays meaningful. A dedicated drag-and-drop calendar and harvest forecasting will come in later releases.</div><div style="height:19px"></div>${action('create','Create a production plan','kind:plan')}`,'Time-based views without duplicate data')}</div>`;}
function analytics(){let bs=all('batch'),species={};state.harvests.forEach(h=>species[h.species]=(species[h.species]||0)+h.weight_lb);let values=Object.entries(species).sort((a,b)=>b[1]-a[1]);let max=Math.max(...values.map(v=>v[1]),1);let expenses=all('expense').reduce((v,r)=>v+Number(d(r).amount||0),0);let sales=(state.summary?.revenue_cents||0)/100;
return tophead('analytics',action('export','↓ Export farm data','','btn ghost'))+`<div class="cards" style="margin-bottom:18px">${stat('Fresh harvested',n(state.summary?.harvest_total_lb,1)+' lb','✳','Actual harvest records')}${stat('Tracked recipes',all('recipe').length,'◫','Substrate experiments')}${stat('Sales revenue',money(state.summary?.revenue_cents),'＄','Recorded fulfilled orders')}${stat('Logged expenses',money(expenses*100),'↘','Manually entered expenses')}</div><div class="grid2" style="margin:0">${panel('Harvests by species',values.length?`<div style="min-height:200px">${values.map(([key,val])=>`<div style="margin:16px 0"><div class="between" style="margin-bottom:8px"><strong>${esc(key)}</strong><span class="subtle">${n(val,2)} lb</span></div><div class="progress" style="height:11px"><div style="width:${val/max*100}%"></div></div></div>`).join('')}</div>`:empty('No harvest trends yet','Record production over time to reveal strain and species performance.'))}${panel('Financial snapshot',`<div class="stack">${[['Gross sales',money(sales*100)],['Entered expenses',money(expenses*100)],['Sales less entered expenses',money((sales-expenses)*100)]].map(v=>`<div class="between" style="padding:12px 0;border-bottom:1px solid var(--edge)"><span class="subtle">${esc(v[0])}</span><strong>${esc(v[1])}</strong></div>`).join('')}</div><div class="notestrip" style="margin-top:20px">These figures are not a formal profit and loss statement. Expenses do not include automatic cost allocation, inventory valuation, labor, or depreciation.</div>`,'Actual sales compared with manually recorded expenses')}</div>`;}
function research(){return tophead('research',can('experiment')?action('create','＋ New experiment','kind:experiment','btn primary'):'')+`<div class="gridhalf" style="margin:0 0 20px">${panel('Controlled experiments',`<p class="subtle">Record a hypothesis, treatments, observations and outcomes. Keep comparisons honest with consistent measurements and adequate replicates.</p>`,'The farm is also a laboratory')}${panel('Quality and incidents',`<p class="subtle">Log contamination and equipment incidents with dates and observations. Visual symptoms alone do not establish organism identity or root cause.</p>${can('incident')?action('create','＋ New incident','kind:incident'):''}`,'Document and learn')}</div><div class="sectionlabel">EXPERIMENTS</div>${recordView('experiment','Add a research question to begin.')}<div class="sectionlabel">INCIDENT LOG</div>${all('incident').length?tableWrap(['Incident','Type','Status','Actions'],all('incident').map(r=>`<tr><td>${esc(d(r).name)}</td><td>${esc(d(r).type)}</td><td>${tag(d(r).status)}</td><td>${can('incident')?action('edit','Edit',r.id):''}</td></tr>`).join('')):empty('No recorded incidents','Track issues by date, batch and room.','incident')}`;}
function equipment(){return tophead('equipment',can('equipment')?action('create','＋ Add equipment','kind:equipment','btn primary'):'')+recordView('equipment','Record your steam processor, autoclaves, humidifiers and other equipment.',['Asset','Location','Maintenance','Condition','Actions'],r=>`<tr><td><strong>${esc(d(r).name)}</strong><div class="tablemeta">${esc(d(r).model||'')}</div></td><td>${esc(d(r).room||'—')}</td><td>${esc(d(r).maintenance||'—')}</td><td>${tag(d(r).status)}</td><td>${can('equipment')?action('edit','Edit',r.id):''}</td></tr>`);}
function team(){let farm=state.farm||{};
return tophead('team',role()==='owner'||role()==='manager'?action('invite','＋ Invite member','','btn primary'):'')+`<div class="grid2" style="margin:0 0 22px">${panel('Unlimited free team members',`<div class="between"><div><h2>${state.members.length} <small class="muted">members · no seat limit</small></h2><p class="subtle">Employees and collaborators are included on every plan, including Free.</p></div>${tag('Free team access')}</div><div class="notestrip" style="margin-top:15px">Invite everyone who helps with your lab, fruiting rooms, harvests, or markets. Each gets their own login and scoped role.</div>`,'No per-person fee, now or later')}${panel('Access philosophy',`<div class="notestrip">Owners manage permissions and billing. Managers administer operations. Cultivation technicians update batches and harvests. Sales teammates manage orders. Viewers can only read. Farms are isolated from one another.</div>`,'Built for growing teams')}</div>`+tableWrap(['Team member','Email','Role','Owner controls'],state.members.map(v=>`<tr><td><div class="tablemain">${esc(v.name)}</div></td><td>${esc(v.email)}</td><td>${tag(v.role)}</td><td>${owner()&&v.role!=='owner'?`<div class="row wrap">${action('member-role','Change role',v.id)}${action('member-remove','Remove',v.id,'btn small ghost')}</div>`:'<span class="subtle">—</span>'}</td></tr>`).join(''))+`<div class="notestrip" style="margin-top:18px">Invitations expire after 7 days. For security, use private invitations and ask staff to choose unique passwords.</div>`;
}

function settings(){return tophead('settings')+`<div class="gridhalf" style="margin:0">${panel('Your workspace',`<div class="stack">${[['Farm',state.farm?.name||'—'],['Your account',state.auth?.email||'—'],['Your role',role()],['Plan',state.farm?.plan||'free'],['Server sync',refreshNeeded()]].map(([k,v])=>`<div class="between" style="padding:11px 0;border-bottom:1px solid var(--edge)"><span class="subtle">${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div>`,'Shared online workspace')}${panel('Backups & portability',`<p class="subtle">Farm records autosave immediately to the server whenever an update succeeds. Download an independent JSON backup to retain control of your data.</p><div class="stack">${action('export','↓ Download farm backup','','btn primary')}${['owner','manager'].includes(role())&&state.farm?.plan!=='free'?action('premium-report','↓ Premium performance report CSV','','btn'):''}${owner()?`<label class="btn" style="text-align:center;cursor:pointer">↑ Import standalone Myco OS backup<input type="file" id="legacyFile" accept=".json" hidden></label>`:''}</div><p class="tiny muted">Legacy imports transfer supported cultivation records only; harvests, orders, and historic stock are excluded to prevent invalid inventory totals.</p>`,'Portable and open-source')}${panel('Billing & subscriptions',`<div class="between"><div><strong>${esc((state.farm?.plan||'free').toUpperCase())}</strong><p class="subtle">${state.farm?.plan==='free'?'Free farm account':'Premium commercial features; unlimited team members remain free'}</p></div>${tag(state.farm?.billing_status||'inactive')}</div><div style="height:16px"></div>${owner()?`<div class="row wrap">${action('plans','View all plans','','btn primary')}${state.farm?.plan!=='free'?action('billing-portal','Manage subscription'):''}</div>`:'<p class="subtle">Only a farm owner can manage billing.</p>'}`,'Billing status is determined by verified Stripe events')}${panel('Appearance & license',`<p class="subtle">Switch between calm dark surfaces and an airy light workspace.</p><div class="row wrap">${action('theme','◐ Toggle dark / light','','btn')}</div><div class="line"></div><strong>© 2026 Hill City Mushrooms</strong><p class="subtle">Myco OS is free and open-source software licensed under the MIT License. You may share, modify, redistribute and commercially host it, provided the required copyright and license notice accompanies copies or substantial portions.</p>${action('license','Read full license')}`,'Built openly, with attribution')}</div></div>`;}
function help(){return tophead('help',action('tour','✧ Start guided tour','','btn primary'))+`<div class="hero" style="min-height:150px"><div><small>WELCOME TO YOUR FIELD GUIDE</small><h2>Small steps. Better growing.</h2><p>Myco OS connects everyday observations to the bigger picture of how your farm is performing.</p></div></div><div class="guidecards">${[['✳','01 · Make a batch','Name your blocks, choose a species, and record an inoculation date.','production'],['⚗','02 · Track cultures','Document your genetics and record a parent culture or source.','laboratory'],['▣','03 · Log processing','Create steam or pressure runs and record the method and duration.','processing'],['◈','04 · Harvest and sell','Harvest against a batch to create stock, then fulfill orders using those lots.','harvests'],['✓','05 · Bring in your crew','Upgrade for extra seats, invite by email and choose a farm role.','team'],['▥','06 · Learn from your data','Use analytics, research logs, and records to make better decisions.','analytics']].map(([ico,title,copy,id])=>`<button class="guidecard" data-action="nav" data-id="${id}"><span class="gico">${ico}</span><strong>${esc(title)}</strong><small>${esc(copy)}</small><span style="color:var(--accent);display:block;margin-top:10px">Explore →</span></button>`).join('')}</div><div class="sectionlabel">WHAT YOU SHOULD KNOW</div><div class="notestrip">Cloud saves require a connection to this server. Updates are acknowledged only after the database confirms them. For offline work use your previous standalone Myco OS version; cross-device offline queuing is not implemented yet.</div>`;}

// Interactive application shell and persisted workflows.
const VIEWS={overview,production,laboratory,recipes,processing,rooms,harvests,inventory,orders,calendar,analytics,tasks,research,equipment,team,settings,help};
const TOUR=[['Welcome to Myco OS','Your farm has its own secure workspace. The sidebar gives you access to production, laboratory work, harvests, inventory, and your team.','overview'],['Start with a cultivation batch','Every harvest links back to a growing batch. Add a batch with its species, strain, block count and inoculation date.','production'],['Track its origin','Add agar plates, cultures and inoculation work to build your culture records.','laboratory'],['Record harvests','Select a batch and enter fresh weight. A traceable inventory lot is created automatically.','harvests'],['Invite your farm crew','On any plan, invite unlimited technicians or market employees with individual passwords and scoped permissions.','team'],['Keep a backup','All successful edits save directly to the server. Export a separate farm JSON backup from Settings.','settings']];
function brand(){return `<span class="mark" aria-hidden="true">✳</span><div class="brandword">MYCO <span>OS</span></div><span class="cloudtag">CLOUD</span>`}
function copyright(){return `<div class="copyright"><span>© 2026 Hill City Mushrooms · Myco OS · MIT Open Source</span><span>Share, modify, and redistribute with copyright and license notice retained.</span></div>`}
function authScreen(){
const mode=state.mode,sign=mode==='signup',isLogin=mode==='login',forgot=mode==='forgot',reset=mode==='reset';
const h=sign?'Create your workspace':isLogin?'Sign in to Myco OS':forgot?'Recover your account':reset?'Choose a new password':'Verify your email';
const body=reset?`<form id="resetForm"><div class="field"><label>New password</label><input name="password" type="password" autocomplete="new-password" required minlength="12" maxlength="256" placeholder="At least 12 characters"></div><button class="btn primary" type="submit" style="margin-top:22px">Update password →</button></form>`:mode==='verify-request'?`<form id="verifyRequestForm"><div class="field"><label>Account email</label><input name="email" type="email" autocomplete="email" required></div><button class="btn primary" type="submit" style="margin-top:22px">Resend verification email →</button></form>`:forgot?`<form id="forgotForm"><div class="field"><label>Account email</label><input name="email" type="email" autocomplete="email" required placeholder="you@yourfarm.com"></div><button class="btn primary" type="submit" style="margin-top:22px">Send recovery link →</button></form>`:`<form id="authForm">${sign?`<div class="field"><label>Your name</label><input name="name" autocomplete="name" required minlength="2" maxlength="120" placeholder="Your name"></div><div class="field"><label>Farm name</label><input name="farm_name" required minlength="2" maxlength="140" placeholder="e.g. Hill City Mushrooms"></div>`:''}<div class="field"><label>Email</label><input name="email" type="email" autocomplete="email" required placeholder="you@yourfarm.com"></div><div class="field"><label>Password</label><input name="password" type="password" autocomplete="${sign?'new-password':'current-password'}" required ${sign?'minlength="12"':''} placeholder="${sign?'At least 12 characters':'Your password'}"></div><div style="height:21px"></div><button type="submit" class="btn primary" ${state.busy?'disabled':''}>${sign?'Create free account →':'Sign in →'}</button></form>`;
return `<div class="authpage"><div class="authleft"><div class="brand">${brand()}</div><div><div class="caps">GROW BETTER. TOGETHER.</div><h1>One place for <span>everything growing.</span></h1><p>Track genetics, production, harvests, inventory and sales with your crew. Every farm has its own private workspace.</p><div class="authchecks"><div class="authcheck">✳ Free personal and team accounts</div><div class="authcheck">◈ Unlimited free employee invitations</div><div class="authcheck">◉ Harvest-to-inventory traceability</div><div class="authcheck">◇ Open source by Hill City Mushrooms</div></div></div><div class="authcopyright">Copyright © 2026 Hill City Mushrooms · MIT licensed open-source software. You may use, share, modify and redistribute with the license notice retained.</div></div><div class="authright"><div class="authbox"><div class="caps">${reset?'SECURE RECOVERY':forgot?'PASSWORD HELP':sign?'START YOUR FARM':isLogin?'WELCOME BACK':'ACCOUNT SECURITY'}</div><h2>${h}</h2><p>${sign?'Start free and invite your team at no extra cost.':isLogin?'Pick up exactly where your crew left off.':reset?'This link can be used only once.':'We’ll email a secure, expiring link if the account exists.'}</p>${body}<div class="authfooter">${sign?'Already have an account?':isLogin?'New to Myco OS?':'Ready to sign in?'} <button class="authlink" data-action="auth-mode" data-id="${sign?'login':isLogin?'signup':'login'}">${sign?'Sign in':isLogin?'Create a farm':'Sign in'}</button></div>${isLogin?`<p class="authfooter"><button class="authlink" data-action="auth-mode" data-id="forgot">Forgot password?</button> · <button class="authlink" data-action="auth-mode" data-id="verify-request">Resend verification</button></p>`:''}<p class="tiny muted" style="margin-top:25px">For public use, HTTPS and managed PostgreSQL backups are required. Your passwords are never included in farm exports.</p></div></div></div>`;
}

function navHtml(){return GROUPS.map(([group,items])=>`<div class="navgroup"><div class="navtitle">${group}</div>${items.map(([id,name])=>`<button class="navitem ${state.page===id?'active':''}" data-action="nav" data-id="${id}"><span class="navico">${icon[id]||'◈'}</span>${name}</button>`).join('')}</div>`).join('')}
function shell(){let f=state.farm||{};return `<div class="mobilebackdrop" data-action="close-menu"></div><div class="shell"><aside class="sidebar"><div class="brand">${brand()}</div><button class="farmselect" data-action="switch-farm" title="Switch farm workspace"><span class="farmavatar">${esc((f.name||'F').slice(0,1).toUpperCase())}</span><span style="min-width:0;flex:1"><strong>${esc(f.name||'Your farm')}</strong><small>${esc(f.plan||'free')} plan · ${esc(f.role||'viewer')}</small></span><span>⌄</span></button>${navHtml()}<div class="sidespace"></div><div class="sidefoot"><strong>✳ Made for growers</strong>© 2026 Hill City Mushrooms<br>MIT licensed open-source software.<div class="sidehelp">New to Myco OS?<br><button data-action="tour">Take the quick tour ↗</button></div></div></aside><main class="main"><header class="topbar"><div class="row"><button class="iconbtn mobilemenu" aria-label="Open navigation" data-action="open-menu">☰</button><span class="crumb">Workspace / <strong>${esc(PAGEINFO[state.page]?.[0]||'Overview')}</strong></span></div><div class="topright"><span class="pill hide-mobile" title="Farm records are saved to the server after each successful update"><span class="dot"></span>${state.lastSync?'Server synced':'Connected workspace'}</span><button class="searchbutton" data-action="search" title="Search records">⌕ Search <span>Ctrl K</span></button><button class="iconbtn" aria-label="Toggle appearance" data-action="theme">◐</button><button class="avatar" data-action="account" title="Your account">${esc((state.auth?.name||'?').slice(0,1).toUpperCase())}</button></div></header><div class="content">${(VIEWS[state.page]||overview)()}${copyright()}</div></main></div>${state.modal?modalHtml():''}`}
function render(){setTheme(state.theme);$('#app').innerHTML=state.auth?shell():authScreen();if(state.page==='recipes'&&state.auth)updateRecipeCalc();}
function modalFrame(title,desc,body,footer='',wide=false){return `<div class="overlay" id="overlay"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalheader"><div><h2>${esc(title)}</h2><p>${esc(desc)}</p></div><button class="iconbtn" data-action="close-modal" aria-label="Close">×</button></div>${body}${footer}</div></div>`}
function formFooter(label='Save changes',formId='editorForm'){return `<div class="modalfooter"><button type="button" class="btn ghost" data-action="close-modal">Cancel</button><button type="submit" form="${formId}" class="btn primary" ${state.busy?'disabled':''}>${label}</button></div>`}
function fieldHtml(def,val){let [key,label,type,required]=def,v=val?.[key]??'';let ty=type||'text';let id='fld-'+key;let control;if(ty.startsWith('select:')){let options=ty.slice(7).split('|');control=`<select id="${id}" name="${esc(key)}" ${required?'required':''}><option value="">Choose…</option>${options.map(o=>`<option value="${esc(o)}" ${o===String(v)?'selected':''}>${esc(o)}</option>`).join('')}</select>`}else if(ty==='textarea'){control=`<textarea id="${id}" name="${esc(key)}" ${required?'required':''}>${esc(v)}</textarea>`}else{control=`<input id="${id}" name="${esc(key)}" type="${ty}" value="${esc(v)}" ${ty==='number'?'step="any"':''} ${required?'required':''} ${ty==='number'&&required?'min="0"':''}>`}
return `<div class="field ${ty==='textarea'?'full':''}"><label for="${id}">${esc(label)}${required?' *':''}</label>${control}</div>`}
function recordModal(kind,id=''){const rec=id?byId(id):null,def=SCHEMAS[kind],name=LABELS[kind]||kind;if(!def)return '';return modalFrame(rec?'Edit '+name.replace(/s$/,''):'New '+name.replace(/s$/,''),'Records sync to the server when you save.',`<form id="editorForm" data-kind="${kind}" data-record="${esc(id)}"><div class="formgrid">${def.map(field=>fieldHtml(field,rec?.data)).join('')}</div></form>`,formFooter(rec?'Save changes':'Create record'),true)}
function harvestModal(){const bs=all('batch');return modalFrame('Record a harvest','Harvest weight will be added to a new traceable fresh inventory lot.',bs.length?`<form id="harvestForm"><div class="formgrid"><div class="field full"><label>Growing batch *</label><select name="batch_id" required>${bs.map(b=>`<option value="${b.id}">${esc(d(b).name)} · ${esc(d(b).species)}</option>`).join('')}</select></div><div class="field"><label>Fresh weight (lb) *</label><input name="weight_lb" type="number" min="0.001" step="0.001" required placeholder="8.50"></div><div class="field"><label>Flush number</label><input name="flush" type="number" min="1" max="20" value="1" required></div><div class="field full"><label>Notes</label><textarea name="note" rows="3" maxlength="2000"></textarea></div></div></form>`:empty('Create a growing batch first','A harvest must be linked to a batch.','batch'),bs.length?formFooter('Save harvest','harvestForm'):'' )}
function orderModal(){const lots=state.stock.filter(v=>v.quantity_lb>0);return modalFrame('Create a customer order','Orders are drafts until fulfilled. Fulfillment deducts inventory.',lots.length?`<form id="orderForm"><div class="formgrid"><div class="field full"><label>Customer *</label><input name="customer" required maxlength="160" placeholder="Restaurant, market, or customer"></div><div class="field full"><label>Harvest lot *</label><select name="lot_id" id="order-lot" required>${lots.map(l=>`<option value="${l.id}">${esc(l.species)} · ${n(l.quantity_lb,2)} lb available · ${l.id.slice(0,8)}</option>`).join('')}</select></div><div class="field"><label>Quantity (lb) *</label><input name="quantity_lb" type="number" required min="0.001" step="0.001" placeholder="2.5"></div><div class="field"><label>Price per pound (USD) *</label><input name="price" type="number" required min="0" step="0.01" value="20"></div></div></form>`:empty('No available inventory','Record a harvest before selling from a lot.'),lots.length?formFooter('Create draft order','orderForm'):'' )}
function inviteModal(){return modalFrame('Invite a teammate','The recipient can join with their own account, using their invited email.',`<form id="inviteForm"><div class="formgrid"><div class="field full"><label>Employee email *</label><input type="email" name="email" required placeholder="employee@example.com"></div><div class="field full"><label>Role</label><select name="role"><option value="technician">Cultivation technician</option><option value="sales">Sales and markets</option><option value="viewer">Read only</option><option value="manager">Manager</option></select></div></div></form>`,formFooter('Create invite link','inviteForm'))}
function farmModal(){return modalFrame('Your farm workspaces','You can own or belong to multiple farms, all with their own isolated data.',`<div class="stack">${state.farms.map(f=>`<button class="btn" data-action="choose-farm" data-id="${f.id}" style="justify-content:flex-start;padding:15px"><span class="farmavatar">${esc(f.name[0]||'F')}</span><span style="flex:1;text-align:left">${esc(f.name)} <span class="tiny muted">· ${esc(f.role)} · ${esc(f.plan)}</span></span>${state.farm?.id===f.id?'✓':''}</button>`).join('')}</div><div class="line"></div><form id="newFarmForm" class="stack"><div class="field"><label>Create another farm workspace (free)</label><input name="name" minlength="2" maxlength="140" required placeholder="Farm name"></div><button class="btn primary" type="submit">＋ Create workspace</button></form>`)}

function plansModal(){const plans=[['Personal','Free','Unlimited people','All core cultivation, harvest, inventory, team collaboration, and JSON exports','free'],['Pro','Managed subscription','Unlimited people','Everything free, plus downloadable advanced species performance CSV reports','pro'],['Growth','Managed subscription','Unlimited people','Pro reports plus room for future premium integrations and automations (not included yet)','growth']];return modalFrame('Choose how you grow','Every plan includes unlimited free members and employee accounts.',`<div class="pricegrid">${plans.map(([name,price,seats,desc,id])=>`<div class="pricecard ${id==='pro'?'featured':''}"><div class="caps">${seats}</div><h3 style="margin-top:12px">${name}</h3><div class="price" style="font-size:23px">${price}</div><p class="subtle">${desc}</p><div class="line"></div>${state.farm?.plan===id?tag('Current plan'):id==='free'?'<span class="subtle">Included for everyone</span>':action('checkout','Choose '+name,id,'btn primary')}</div>`).join('')}</div><p class="tiny muted">Plans are not activated until Stripe prices are configured and you explicitly complete checkout. Growth currently supports the same implemented features as Pro. Planned features are not included in your purchase today.</p>`,'',true)}

function tourModal(){let [t,desc,page]=TOUR[state.tour]||TOUR[0];return modalFrame(`${state.tour+1} of ${TOUR.length} · ${t}`,'Your interactive guide to the farm workspace',`<div class="hero" style="margin:0;min-height:130px"><div><small>FIELD GUIDE · MYCO OS</small><h2>${esc(t)}</h2><p>${esc(desc)}</p></div></div><div class="progress" style="margin-top:18px"><div style="width:${(state.tour+1)/TOUR.length*100}%"></div></div>`,`<div class="modalfooter"><button class="btn ghost" data-action="close-modal">Skip</button>${state.tour?`<button class="btn ghost" data-action="tour-prev">← Previous</button>`:''}<button class="btn primary" data-action="tour-next">${state.tour===TOUR.length-1?'Finish tour ✓':'Continue →'}</button></div>`)}
function batchModal(id){let b=byId(id),data=d(b),hh=state.harvests.filter(h=>h.batch_id===id),total=hh.reduce((a,h)=>a+h.weight_lb,0),dry=Number(data.dry_lb||0)*Number(data.blocks||0),be=dry>0?((total/dry)*100).toFixed(1)+'%':'Not enough dry mass data';return modalFrame(data.name||'Batch details',`${data.species||'Unknown species'} · ${data.strain||'Unspecified strain'}`,`<div class="cards" style="grid-template-columns:repeat(3,1fr)">${stat('Blocks',data.blocks||'—','▣')}${stat('Harvest total',n(total,2)+' lb','✳')}${stat('Biol. efficiency',be,'◈')}</div><div class="line"></div><div class="between"><span class="subtle">Current stage</span>${tag(data.status||'Planned')}</div><p class="subtle">${esc(data.notes||'No batch notes yet.')}</p><div class="sectionlabel">HARVEST HISTORY</div>${hh.length?tableWrap(['Date','Weight','Flush'],hh.map(h=>`<tr><td>${date(h.harvested_at)}</td><td>${n(h.weight_lb,2)} lb</td><td>${h.flush}</td></tr>`).join('')):empty('Not harvested yet','Use Record harvest to add a linked fresh inventory lot.')}<p class="tiny muted">Biological efficiency = harvested fresh weight ÷ (dry mass per block × original block count) × 100. Excludes unrecorded harvests.</p>`, `<div class="modalfooter"><button class="btn ghost" data-action="close-modal">Close</button>${can('batch')?action('edit','Edit batch',id,'btn primary'):''}</div>`,true)}
function licenseModal(){return modalFrame('MIT License','Myco OS · Copyright © 2026 Hill City Mushrooms',`<div style="font-size:12px;line-height:1.9;color:var(--muted)">Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the "Software"), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions:<p>The above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software.</p><p>THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.</p></div>`)}
function modalHtml(){let m=state.modal;switch(m.type){case 'record':return recordModal(m.kind,m.id);case 'harvest':return harvestModal();case 'order':return orderModal();case 'invite':return inviteModal();case 'plans':return plansModal();case 'farm':return farmModal();case 'tour':return tourModal();case 'batch':return batchModal(m.id);case 'license':return licenseModal();case 'invite-url':return modalFrame('Invite link created','Share this private link with your teammate.',`<div class="notestrip" style="word-break:break-all">${esc(m.url)}</div><div class="modalfooter"><button class="btn primary" data-action="copy-invite">Copy link</button></div>`);case 'account':return modalFrame('Account & security',state.auth?.email||'',`<div class="stack"><strong>${esc(state.auth?.name||'Farm member')}</strong><form id="changePasswordForm" class="stack"><div class="field"><label>Current password</label><input name="current_password" type="password" autocomplete="current-password" required></div><div class="field"><label>New password (12+ characters)</label><input name="new_password" type="password" autocomplete="new-password" required minlength="12"></div><button type="submit" class="btn primary">Change password & sign out other devices</button></form><div class="line"></div>${action('logout','Sign out','','btn danger')}</div>`);case 'member-role':{let u=state.members.find(v=>v.id===m.id);return modalFrame('Edit member permissions',u?.email||'',`<form id="memberRoleForm" data-uid="${esc(m.id)}"><div class="field"><label>Access level</label><select name="role">${['manager','technician','sales','viewer'].map(r=>`<option value="${r}" ${u?.role===r?'selected':''}>${r}</option>`).join('')}</select></div></form>`,formFooter('Save role','memberRoleForm'))};default:return ''}}
function openModal(m){state.modal=m;render()}
function closeModal(){state.modal=null;render()}
async function loadFarm(fid){const [sum,recs,hs,st,os,ms]=await Promise.all([api(`/api/farms/${fid}/summary`),api(`/api/farms/${fid}/records`),api(`/api/farms/${fid}/harvests`),api(`/api/farms/${fid}/stock`),api(`/api/farms/${fid}/orders`),api(`/api/farms/${fid}/members`)]);state.summary=sum;state.records=recs;state.harvests=hs;state.stock=st;state.orders=os;state.members=ms;state.lastSync=Date.now();state.farm={...sum.farm};state.query='';}
async function reload(){if(!state.farm?.id)return;await loadFarm(state.farm.id);render()}
async function refreshSession(){try{let u=await api('/api/auth/me');state.auth=u.user;state.csrf=u.csrf;state.farms=u.farms;const choice=state.farms.find(f=>f.id===state.farm?.id)||state.farms[0];if(choice)await loadFarm(choice.id);else{state.auth=null;state.farm=null}}catch(e){state.auth=null;state.farm=null}render();if(state.auth){const params=new URLSearchParams(location.search);if(params.has('invite')){try{await api('/api/invites/accept','POST',{token:params.get('invite')});history.replaceState({},'',location.pathname);toast('Invitation accepted');await refreshSession()}catch(e){toast(e.message,true)}}}}
async function handleAuth(form){const data=Object.fromEntries(new FormData(form));state.busy=true;try{let path=state.mode==='login'?'/api/auth/login':'/api/auth/signup';let response=await api(path,'POST',data);if(response.verification_required){state.mode='login';render();toast('Account created. Check your email to verify it before signing in.');return}state.csrf=response.csrf;state.auth=response.user;await refreshSession();toast('Welcome to Myco OS')}catch(e){toast(e.message,true)}finally{state.busy=false}}
function formDataObject(form){const data={};for(const [key,value] of new FormData(form)){const field=SCHEMAS[form.dataset.kind]?.find(v=>v[0]===key);data[key]=field?.[2]==='number'?(value===''?null:Number(value)):String(value)}return data}
async function handleForm(form){if(state.busy)return;state.busy=true;const id=form.id;try{if(id==='authForm'){await handleAuth(form);return}if(id==='editorForm'){const kind=form.dataset.kind;const rid=form.dataset.record;const data=formDataObject(form);if(kind==='batch'&&(!Number.isFinite(data.blocks)||data.blocks<1))throw Error('Block count must be at least 1');if(rid){let r=byId(rid);await api(root()+`/records/${rid}`,'PUT',{revision:r.revision,data})}else await api(root()+'/records','POST',{kind,data});toast('Farm record saved')}else if(id==='harvestForm'){let dta=Object.fromEntries(new FormData(form));await api(root()+'/harvests','POST',{batch_id:dta.batch_id,weight_lb:Number(dta.weight_lb),flush:Number(dta.flush),note:dta.note});toast('Harvest saved and inventory updated')}else if(id==='orderForm'){const data=Object.fromEntries(new FormData(form));const cost=Math.round(Number(data.price)*100);await api(root()+'/orders','POST',{customer:data.customer,lines:[{lot_id:data.lot_id,quantity_lb:Number(data.quantity_lb),unit_price_cents:cost}]});toast('Draft order created')}else if(id==='newFarmForm'){let out=await api('/api/farms','POST',Object.fromEntries(new FormData(form)));await refreshSession();await loadFarm(out.id);state.modal=null;render();toast('Workspace created');return}else if(id==='memberRoleForm'){await api(root()+'/members/'+form.dataset.uid,'PATCH',Object.fromEntries(new FormData(form)));toast('Permissions updated')}else if(id==='changePasswordForm'){await api('/api/auth/password/change','POST',Object.fromEntries(new FormData(form)));toast('Password updated. Other devices were signed out');state.modal=null;render();return}else if(id==='forgotForm'){const out=await api('/api/auth/password/forgot','POST',Object.fromEntries(new FormData(form)));state.mode='login';render();toast(out.message);return}else if(id==='verifyRequestForm'){const out=await api('/api/auth/verify/resend','POST',Object.fromEntries(new FormData(form)));state.mode='login';render();toast(out.message);return}else if(id==='resetForm'){const params=new URLSearchParams(location.search);const out=await api('/api/auth/password/reset','POST',{token:params.get('reset'),...Object.fromEntries(new FormData(form))});history.replaceState({},'',location.pathname);state.mode='login';render();toast(out.message);return}else if(id==='inviteForm'){let out=await api(root()+'/invites','POST',Object.fromEntries(new FormData(form)));state.modal={type:'invite-url',url:out.invite_url};await reload();render();return}state.modal=null;await reload()}catch(e){toast(e.message,true)}finally{state.busy=false}}
function download(filename,body){let blob=new Blob([body],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
async function command(actionName,id){try{switch(actionName){case 'nav':if(!VIEWS[id])return;state.page=id;state.query='';state.modal=null;document.body.classList.remove('openmenu');render();scrollTo({top:0,behavior:'smooth'});return;case 'open-menu':document.body.classList.add('openmenu');return;case 'close-menu':document.body.classList.remove('openmenu');return;case 'close-modal':closeModal();return;case 'auth-mode':state.mode=id||'login';render();return;case 'theme':setTheme(state.theme==='dark'?'light':'dark');return;case 'create':openModal({type:'record',kind:id.replace('kind:','')});return;case 'edit':{const r=byId(id);if(r)openModal({type:'record',kind:r.kind,id});return}case 'batch-info':openModal({type:'batch',id});return;case 'new-harvest':openModal({type:'harvest'});return;case 'new-order':openModal({type:'order'});return;case 'invite':openModal({type:'invite'});return;case 'plans':openModal({type:'plans'});return;case 'switch-farm':openModal({type:'farm'});return;case 'choose-farm':state.modal=null;await loadFarm(id);render();return;case 'license':openModal({type:'license'});return;case 'account':openModal({type:'account'});return;case 'member-role':openModal({type:'member-role',id});return;case 'member-remove':if(!confirm('Remove this member from this farm? Their account and other farm memberships remain intact.'))return;await api(root()+'/members/'+id,'DELETE',{});toast('Team member removed');await reload();return;case 'premium-report':{const res=await fetch(root()+'/reports/performance.csv',{credentials:'same-origin'});if(!res.ok){const body=await res.json().catch(()=>({}));throw Error(body.detail||'Report unavailable')}const blob=await res.blob();const url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download='myco-performance-'+today()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Performance CSV downloaded');return}case 'tour':state.tour=0;openModal({type:'tour'});return;case 'tour-next':if(state.tour<TOUR.length-1){state.tour++;state.page=TOUR[state.tour][2];render()}else{state.modal=null;render()}return;case 'tour-prev':state.tour=Math.max(0,state.tour-1);state.page=TOUR[state.tour][2];render();return;case 'copy-invite':await navigator.clipboard.writeText(state.modal.url);toast('Invite link copied');return;case 'logout':await api('/api/auth/logout','POST',{});state.auth=null;state.csrf='';state.farm=null;state.modal=null;render();return;case 'finish-task':{const task=byId(id);if(!task)return;await api(root()+`/records/${id}`,'PUT',{revision:task.revision,data:{...task.data,status:'Done'}});toast('Task marked complete');await reload();return}case 'fulfill':if(!confirm('Fulfill this order and deduct its weight from stock?'))return;await api(root()+`/orders/${id}/fulfill`,'POST',{});toast('Order fulfilled and inventory deducted');await reload();return;case 'export':{const out=await api(root()+'/export');download(`myco-os-${(state.farm.name||'farm').toLowerCase().replace(/[^a-z0-9]+/g,'-')}-${today()}.json`,JSON.stringify(out,null,2));toast('Farm export downloaded');return}case 'checkout':{const out=await api(root()+'/billing/checkout','POST',{plan:id});location.href=out.url;return}case 'billing-portal':{const out=await api(root()+'/billing/portal','POST',{});location.href=out.url;return}case 'search':{state.page='production';render();$('#listSearch')?.focus();return}default:return}}catch(e){toast(e.message,true)}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b){if(e.target.id==='overlay')closeModal();return}if(b.dataset.action==='logout'&&!confirm('Sign out of this device?'))return;command(b.dataset.action,b.dataset.id||'')});
document.addEventListener('submit',e=>{if(['authForm','editorForm','harvestForm','orderForm','inviteForm','newFarmForm','memberRoleForm','changePasswordForm','forgotForm','resetForm','verifyRequestForm'].includes(e.target.id)){e.preventDefault();handleForm(e.target)}});
document.addEventListener('input',e=>{if(e.target.id==='listSearch'){state.query=e.target.value;const focus=e.target.selectionStart;render();let inp=$('#listSearch');if(inp){inp.focus();inp.setSelectionRange(focus,focus)}}else if(e.target.id?.startsWith('recipe-'))updateRecipeCalc()});
document.addEventListener('change',async e=>{if(e.target.id==='legacyFile'){let file=e.target.files?.[0];if(!file)return;if(!confirm('Import supported records from this backup? This will add records; it does not replace existing data.'))return;try{let data=JSON.parse(await file.text());let out=await api(root()+'/import-legacy','POST',data);toast(`${out.imported} records imported; legacy stock and sales were not imported`);await reload()}catch(err){toast(err.message,true)}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal)closeModal();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(state.auth)command('search','')}});
setTheme(state.theme);const entryParams=new URLSearchParams(location.search);if(entryParams.has('reset')){state.mode='reset';render()}else if(entryParams.has('verify')){api('/api/auth/verify','POST',{token:entryParams.get('verify')}).then(()=>{history.replaceState({},'',location.pathname);state.mode='login';toast('Email verified. You can now sign in.');render()}).catch(e=>{state.mode='verify-request';render();toast(e.message,true)})}else refreshSession();
// Refresh remote edits while the page is in focus; avoid replacing open forms.
setInterval(async()=>{if(!state.auth||!state.farm||state.modal||document.hidden)return;try{await loadFarm(state.farm.id);render()}catch(e){/* keep last displayed records; server error will appear on next edit */}},30000);
